from lib import *
S = SS('g52')
steps = [
    step("丢掉不 Stop 的定时器,GC 之后堆有没有增长(go.mod 写 go 1.27,每种 10 万个):NewTicker(1h)、time.Tick(1h)、NewTimer(1h),以及在循环里每轮 select 放一个 time.After(1h),堆都是 0.2 MB → 0.2 MB,增加 0.0 MB。对照:把 10 万个 NewTicker(1h) 放进切片保留,堆 0.2 MB → 26.0 MB,增加 25.8 MB。", t=tl(S(1)), done=lidx(S(1), 'NewTicker(1h) 丢掉不 Stop', 'time.Tick(1h) 丢掉', 'NewTimer(1h) 丢掉不 Stop', '每次 select 里放一个'), mark=lidx(S(1), '放进切片保留'), b=bars([['丢掉的 NewTicker:堆增加(MB)', 0.0, '0.0'], ['丢掉的 time.After 循环', 0.0, '0.0'], ['保留在切片里的 NewTicker', 25.8, '25.8']], 25.8, done=[0, 1], mark=[2]), kv=KV([['丢掉不 Stop', 'GC 后堆不增长'], ['保留引用', '10 万个增加 25.8 MB'], ['含义', '没有引用的定时器能被 GC 回收']], ['含义'])),
    step("想复现“Go 1.23 之前会泄漏”,在这个工具链上做不到:GODEBUG=asynctimerchan=1 直接 fatal error: removed GODEBUG \"asynctimerchan\" set to old value \"1\" in environment;go.mod 改成 go 1.22,同一份程序的结果也是堆 0.2 MB → 0.2 MB,select+time.After 循环同样不增长。godebug.md 里写着 Go 1.27 removed the `asynctimerchan` setting,以及旧条目 This setting will be removed in Go 1.27。", t=tl(S(2)), done=lidx(S(2), 'go.mod 写 go 1.22'), mark=lidx(S(2), 'fatal error', 'godebug.md:171', 'godebug.md:358'), kv=KV([['asynctimerchan=1', 'Go 1.27 直接 fatal error'], ['go.mod 写 go 1.22', '也不泄漏'], ['原因', 'Go 1.27 删掉了这个设置(godebug 文档)'], ['旧行为', '本机没有旧工具链,没法实测']], ['旧行为'])),
    step("没有泄漏不等于没有成本:一百万轮热循环里,每轮 select 放一个 time.After(1h) 是 3 次分配、145 ns/轮;复用一个 Timer 并每轮 Reset 是 0 次分配、83 ns/轮。", t=tl(S(3)), mark=lidx(S(3), '每轮 select 里放 time.After'), b=bars([['time.After 每轮(ns)', 145, '145'], ['复用 Timer + Reset 每轮(ns)', 83, '83']], 145, mark=[0], done=[1]), kv=KV([['time.After', '3 次分配,145 ns/轮'], ['复用 Timer', '0 次分配,83 ns/轮'], ['结论', '不泄漏了,但热路径上仍有分配']], ['结论'])),
    step("仍然保留的 Ticker 遇到慢接收方会丢 tick:周期 10 ms 的 Ticker,接收方每次处理 55 ms,600 ms 里只收到 11 个 tick(按周期应有 60 个)。文档对应的一句是 The ticker will adjust the time interval or drop ticks to make up for slow receivers。", t=tl(S(4)), mark=lidx(S(4), '收到 11 个 tick'), kv=KV([['周期', '10 ms'], ['接收方处理', '55 ms 一次'], ['600 ms 里收到', '11 个(按周期应有 60 个)']], ['600 ms 里收到'])),
    step("文档原文(go doc):NewTicker——Before Go 1.23 垃圾回收器不回收没有到期或没有 Stop 的 ticker,所以代码常在 NewTicker 之后立刻 defer t.Stop;As of Go 1.23, the garbage collector can recover unreferenced tickers, even if they haven't been stopped;但 Code may of course still want to call Stop to stop the ticker for other reasons。time.After:There is no reason to prefer NewTimer when After will do。", t=tl(S(5)), done=lidx(S(5), 'As of Go 1.23, the garbage collector can recover unreferenced', 'tickers, even if they haven'), mark=lidx(S(5), 'Code may of course still want', 'prefer NewTimer when After'), kv=KV([['Go 1.23 之前', '没到期/没 Stop 的 ticker 不被回收'], ['Go 1.23 起', '没有引用的 ticker 可被回收'], ['仍要 Stop 的情形', '需要停止它(不让它再产生事件)等其它原因']], ['Go 1.23 起'])),
]
A = mkartg('g52', 52, 'Go,Ticker,time.After,泄漏,GC,真实验证,动画演示',
    '在 Go 1.27.1 里验证定时器泄漏:丢掉不 Stop 的 NewTicker、time.Tick、NewTimer 和循环里的 time.After,GC 后堆都不增长,而保留引用的 10 万个 Ticker 占 25.8 MB;旧的 asynctimerchan 设置在 1.27 已被删除,无法复现 1.23 之前的泄漏;time.After 每轮 3 次分配 145 ns,复用 Timer 0 次分配 83 ns;慢接收方会丢 tick。',
    '“循环里用 time.After 会泄漏”是老 Go 的经典坑。Go 1.23 起文档说垃圾回收器能回收没有引用的定时器。这篇在 1.27.1 上实测它是否还泄漏,发现旧行为本机已经复现不出来,并量出仍然存在的分配成本。',
    [('0.0 MB', '丢掉 10 万个不 Stop 的 NewTicker,GC 之后堆的增长'), ('25.8 MB', '同样 10 万个 Ticker 放进切片保留之后的增长'), ('145 vs 83 ns', '热循环每轮 time.After 与复用 Timer 的耗时')],
    [('没有引用就能回收', '<p>在 go.mod 写 go 1.27 的程序里,丢掉不 Stop 的 10 万个 <code>NewTicker</code>、<code>time.Tick</code>、<code>NewTimer</code>,以及循环里 10 万次 <code>select</code> 放 <code>time.After</code>,GC 之后堆都没有增长;把 Ticker 保留在切片里就增长 25.8 MB。可见回收是靠“没有引用”,不是靠 Stop。</p>'),
     ('旧泄漏我复现不了', '<p>老版本的泄漏需要 <code>asynctimerchan=1</code> 之类的旧行为。Go 1.27 把这个设置删了(设置它会直接 fatal error),go.mod 写 go 1.22 的同一程序也不泄漏。我机器上只有 1.27.1 工具链,所以“Go 1.23 之前确实泄漏”这一点只来自官方文档的描述,我没有实测。</p>'),
     ('成本还在', '<p>不泄漏不代表便宜:热循环里每轮 <code>time.After</code> 要 3 次分配、145 ns,复用一个 <code>Timer</code> 并 <code>Reset</code> 是 0 次分配、83 ns。每轮处理量很小的循环里,这个差别才值得处理;一般代码用 <code>time.After</code> 就够了,文档也这么说。</p>'),
     ('Ticker 仍会丢 tick', '<p>接收方比周期慢时,Ticker 不会攒着补发:周期 10 ms、每次处理 55 ms,600 ms 只收到 11 个 tick。需要“一个都不能少”的场景不能靠 Ticker。</p>'),
     ('什么时候还要 Stop', '<p>文档的说法是 Stop 不再是为了让 GC 回收,但你仍可能因为别的原因想停掉它,比如不再需要它产生事件。这一点我没有再单独设计实验。</p>')],
    steps,
    [ENV_G + '。堆数字 = 两次 runtime.GC() 后的 HeapAlloc,每种 10 万个;go.mod 写 go 1.22 的对照由同一个工具链(1.27.1)编译;对照实验“保留在切片里”用来确认测量方法能看到增长;热循环成本各 100 万轮,单次测量;读过的文档:go doc time.NewTicker / time.After,godebug.md 中 asynctimerchan 的两处',
     '没有验证:Go 1.23 之前的泄漏行为(本机没有旧工具链)、1.23 之后 GC 回收定时器的具体机制、time.Tick 在长期运行服务里的实际影响、在多 goroutine 并发创建下的表现、Stop 的其它用途(此处没有单独实验)'],
    'Ticker 与 time.After 泄漏')
